const h = React.createElement;
const staggerFrames = Math.round(0.3 * fps);

const cards = [
  { name: 'Theo Browne', quote: '\u201cGPT-5.5 is smart, weird, hard to wrangle, and too expensive.\u201d', border: D.violet, delay: 0 },
  { name: 'CodeRabbit', sub: 'Production Tests', quote: '\u201cIssue detection: 58% \u2192 79% \u2014 only with extremely specific prompts.\u201d', border: D.cyan, delay: staggerFrames },
  { name: 'Cursor Co-founder', quote: '\u201cGPT-5.5? Brilliant intern. Claude? Senior engineer.\u201d', border: D.violet, delay: staggerFrames * 2 },
];

const cardH = Math.round(height * 0.2);
const gap = Math.round(height * 0.035);
const totalH = cards.length * cardH + (cards.length - 1) * gap;
const startY = (height - totalH) / 2;

const wmProg = interpolate(frame, [0, Math.max(1, Math.round(fps * 0.5))], [0, 0.06], { extrapolateRight: 'clamp', extrapolateLeft: 'clamp' });
const watermark = h('div', { style: {
  position: 'absolute', right: width * 0.04, top: height * 0.02,
  fontSize: height * 0.55, fontFamily: D.font_display, color: D.text,
  opacity: wmProg, lineHeight: 1, userSelect: 'none', pointerEvents: 'none'
} }, '\u201C');

const cardEls = cards.map(function(card, i) {
  const prog = frame >= card.delay
    ? spring({ frame: frame - card.delay, fps: fps, config: { damping: 14, stiffness: 180 } })
    : 0;
  const x = interpolate(prog, [0, 1], [-width * 0.7, 0]);
  const opacity = interpolate(prog, [0, 0.3], [0, 1], { extrapolateRight: 'clamp', extrapolateLeft: 'clamp' });
  const y = startY + i * (cardH + gap);

  const glowAlpha = interpolate(prog, [0.8, 1], [0, 0.35], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  const shadow = '0 6px 32px rgba(0,0,0,0.5), -4px 0 20px ' + card.border + String(Math.round(glowAlpha * 255).toString(16)).padStart(2, '0');

  return h('div', {
    key: i,
    style: {
      position: 'absolute',
      left: Math.round(width * 0.08 + x),
      top: y,
      width: Math.round(width * 0.84),
      height: cardH,
      background: D.surface,
      borderLeft: '6px solid ' + card.border,
      borderRadius: 14,
      opacity: opacity,
      display: 'flex',
      flexDirection: 'column',
      justifyContent: 'center',
      padding: '0 40px',
      boxShadow: shadow,
    }
  },
    h('div', { style: {
      color: D.text, fontFamily: D.font_display,
      fontSize: Math.round(height * 0.032), lineHeight: 1.5,
      marginBottom: Math.round(height * 0.012)
    } }, card.quote),
    h('div', { style: {
      color: card.border, fontFamily: D.font_mono,
      fontSize: Math.round(height * 0.022), fontWeight: 700, letterSpacing: 0.5
    } }, '\u2014 ' + card.name + (card.sub ? '  \u00b7  ' + card.sub : ''))
  );
});

return h(AbsoluteFill, { style: { background: D.bg } }, watermark, ...cardEls);
